// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, type(uint256).max / 2);
        // configure c with a functional log contract
        Logger log = new Logger();
        c.SetLogFile(address(log));
        // rule: once the log file is set, any deposit by any actor of any amount succeeds
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract Logger {
    function AddMessage(address, uint, string memory) public pure {}
}
